 x=cell(m,'128k');y=cell(m,'256k');paragraph(f'- {m}: 128K→256K TG {x["TG"]:.1f}→{y["TG"]:.1f} ({100*(y["TG"]/x["TG"]-1):+.1f}%); TTFT {x["TTFT_s"]:.2f}→{y["TTFT_s"]:.2f} s; wall {x["wall_s"]:.2f}→{y["wall_s"]:.2f} s.')
